def _is_index(token):
    return token != '' and all(c in '0123456789' for c in token)


def _decode(token):
    return token.replace('~1', '/').replace('~0', '~')


def _tokens(pointer):
    if not pointer.startswith('/'):
        raise KeyError(pointer)
    return [_decode(t) for t in pointer[1:].split('/')]


def _step(node, token):
    if isinstance(node, dict):
        return node[token]
    if isinstance(node, list):
        if not _is_index(token) or int(token) >= len(node):
            raise KeyError(token)
        return node[int(token)]
    raise KeyError(token)


def resolve(doc, pointer):
    if pointer == '':
        return doc
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, list):
        if last == '-':
            node.append(value)
        elif _is_index(last) and int(last) < len(node):
            node[int(last)] = value
        else:
            raise KeyError(last)
    elif isinstance(node, dict):
        node[last] = value
    else:
        raise KeyError(last)

